INSERT INTO "public"."about" ("id", "title_en", "title_kh", "title_zh", "image", "createdAt", "updatedAt") VALUES (60, 'Cambodia is a Southeast Asian nation whose landscape spans low-lying plains, the Mekong Delta, mountains and Gulf of Thailand coastline. Phnom Penh, its capital, is home to the art deco Central Market, glittering Royal Palace and the National Museum''s historical and archaeological exhibits. In the country''s northwest are the ruins of Angkor Wat, a massive stone temple complex built during the Khmer Empire.', 'ប្រទេសកម្ពុជាជាប្រទេសអាស៊ីអាគ្នេយ៍ដែលមានទេសភាពលាតសន្ធឹងលើវាលទំនាប ដីសណ្ដទន្លេមេគង្គ ភ្នំ និងឈូងសមុទ្រថៃ។ រាជធានី​ភ្នំពេញ​ជា​រាជធានី​របស់​ខ្លួន​ជា​ទី​តាំង​នៃ​ផ្សារ​ធំ​ថ្មី​ដែល​មាន​ភាព​ស្រស់​ស្អាត​នៃ​ព្រះបរមរាជវាំង និង​វត្ថុ​តាំង​បង្ហាញ​ប្រវត្តិសាស្ត្រ និង​បុរាណវត្ថុ​របស់​សារមន្ទីរជាតិ។ នៅភាគពាយ័ព្យនៃប្រទេសមានប្រាសាទអង្គរវត្តជាប្រាសាទថ្មដ៏ធំដែលត្រូវបានកសាងឡើងក្នុងសម័យអាណាចក្រខ្មែរ។', '柬埔寨是東南亞國家，地形涵蓋平原、湄公河三角洲、山脈和泰國灣。首都金邊擁有美麗的大巴札、大皇宮以及收藏著許多歷史和考古文物的國家博物館。在柬埔寨西北部，坐落著吳哥窟，這是一座建於高棉帝國時期的宏偉石質寺廟。', 'data:image/jpeg;base64,', '2026-07-01 14:36:46.162641', '2026-07-01 14:36:46.162641');
COMMIT;

