BEGIN;
INSERT INTO "public"."about_detail" ("id", "type", "title_en", "title_kh", "title_zh", "createdAt", "updatedAt") VALUES (3, 'History', 'Modern Era (1993 – Present): Sparked by the 1991 Paris Peace Agreements, the monarchy was restored. The country, with its capital at Phnom Penh, has rebuilt its economy, joined ASEAN, and undergone rapid development under long-term leadership.', 'សម័យទំនើប (១៩៩៣ – បច្ចុប្បន្ន): បន្ទាប់ពីកិច្ចព្រមព្រៀងសន្តិភាពទីក្រុងប៉ារីស ឆ្នាំ១៩៩១ របបរាជានិយមត្រូវបានស្ដារឡើងវិញ។ ប្រទេសកម្ពុជា ដែលមានរាជធានីភ្នំពេញ ជាមជ្ឈមណ្ឌល បានកសាងសេដ្ឋកិច្ចឡើងវិញ ចូលជាសមាជិកអាស៊ាន និងមានការអភិវឌ្ឍយ៉ាងឆាប់រហ័សក្រោមការដឹកនាំរយៈពេលវែង។', '现代时期（1993年至今）： 在1991年《巴黎和平协定》的推动下，柬埔寨恢复了君主制。以金边为首都的柬埔寨重建了经济，加入了东盟，并在长期领导下实现了快速发展。', '2026-07-02 02:43:09.399697', '2026-07-02 02:43:09.399697');
INSERT INTO "public"."about_detail" ("id", "type", "title_en", "title_kh", "title_zh", "createdAt", "updatedAt") VALUES (8, 'History', 'Vietnamese Occupation & PRK (1979 – 1993): Vietnamese forces ousted the Khmer Rouge and established the People''s Republic of Kampuchea (PRK), while armed conflict continued for more than a decade.', 'សម័យការគ្រប់គ្រងដោយវៀតណាម និងសាធារណរដ្ឋប្រជាមានិតកម្ពុជា (១៩៧៩ – ១៩៩៣): កងកម្លាំងវៀតណាមបានផ្តួលរំលំរបបខ្មែរក្រហម និងបង្កើតសាធារណរដ្ឋប្រជាមានិតកម្ពុជា (PRK) ខណៈដែលជម្លោះប្រដាប់អាវុធបានបន្តអស់រយៈពេលជាងមួយទសវត្សរ៍។', '越南占领时期与柬埔寨人民共和国（1979—1993年）： 越南军队推翻了红色高棉政权，建立了柬埔寨人民共和国（PRK），与此同时，武装冲突持续了十多年', '2026-07-02 04:37:44.24868', '2026-07-02 04:41:57.842131');
INSERT INTO "public"."about_detail" ("id", "type", "title_en", "title_kh", "title_zh", "createdAt", "updatedAt") VALUES (9, 'Geography', 'Wet Season: May to early November, brought by the moisture-heavy southwest monsoon, delivering the highest rainfall.', 'រដូវភ្លៀង: ចាប់ពីខែឧសភា ដល់ដើមខែវិច្ឆិកា ដែលបណ្តាលមកពីខ្យល់មូសុងនិរតីមានសំណើមខ្ពស់ នាំមកនូវទឹកភ្លៀងច្រើនបំផុត។', '雨季： 五月至十一月初，由湿润的西南季风带来，降雨量最高。', '2026-07-02 07:17:51.458134', '2026-07-02 07:17:51.458134');
INSERT INTO "public"."about_detail" ("id", "type", "title_en", "title_kh", "title_zh", "createdAt", "updatedAt") VALUES (10, 'Geography', 'Dry Season: Mid-November to May, influenced by the northeast monsoon.', 'រដូវប្រាំង: ចាប់ពីពាក់កណ្តាលខែវិច្ឆិកា ដល់ខែឧសភា ដែលមានឥទ្ធិពលពីខ្យល់មូសុងឦសាន។', '旱季： 十一月中旬至五月，受东北季风影响。', '2026-07-02 07:18:43.027181', '2026-07-02 07:18:43.027181');
INSERT INTO "public"."about_detail" ("id", "type", "title_en", "title_kh", "title_zh", "createdAt", "updatedAt") VALUES (11, NULL, NULL, NULL, NULL, '2026-07-03 02:16:58.104701', '2026-07-03 02:16:58.104701');
COMMIT;

