INSERT INTO "public"."province_details" ("id", "description_en", "description_kh", "description_zh", "history_en", "history_kh", "history_zh", "provinceId", "attractions_en", "attractions_kh", "attractions_zh", "food_en", "food_kh", "food_zh", "festival_en", "festival_kh", "festival_zh", "best_time_en", "best_time_kh", "best_time_zh", "createdAt", "updatedAt") VALUES (3, 'Siem Reap is the most famous tourist province in Cambodia.', 'សៀមរាបជាខេត្តទេសចរណ៍ល្បីបំផុតនៅកម្ពុជា', '暹粒是柬埔寨最著名的旅游省份', 'Siem Reap has a long history connected to Angkor Wat.', NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-06-26 02:35:11.748479', '2026-06-26 02:35:11.748479');
INSERT INTO "public"."province_details" ("id", "description_en", "description_kh", "description_zh", "history_en", "history_kh", "history_zh", "provinceId", "attractions_en", "attractions_kh", "attractions_zh", "food_en", "food_kh", "food_zh", "festival_en", "festival_kh", "festival_zh", "best_time_en", "best_time_kh", "best_time_zh", "createdAt", "updatedAt") VALUES (2, 'Siem Reap is the vibrant gateway to the world-renowned ancient temples of Angkor, including the majestic Angkor Wat. Located in northwestern Cambodia, the city beautifully blends French-colonial architecture with bustling markets, a thriving culinary scene, and a rich, deeply rooted Khmer heritage please translate khmer and chinesss', 'សៀមរាបគឺជាច្រកចូលដ៏រស់រវើកទៅកាន់ប្រាសាទបុរាណអង្គរដ៏ល្បីល្បាញលើពិភពលោក រួមទាំងប្រាសាទអង្គរវត្តដ៏អស្ចារ្យ។ ស្ថិតនៅភាគពាយ័ព្យនៃប្រទេសកម្ពុជា ទីក្រុងនេះរួមបញ្ចូលគ្នាយ៉ាងស្រស់ស្អាតនូវស្ថាបត្យកម្មបែបអាណានិគមបារាំង ទីផ្សារដ៏មមាញឹក វប្បធម៌ម្ហូបអាហារដ៏សម្បូរបែប និងបេតិកភណ្ឌវប្បធម៌ខ្មែរដ៏សម្បូរបែបដែលមានឫសគល់យ៉ាងជ្រាលជ្រៅ។', '暹粒是通往世界著名吴哥古迹群的重要门户，其中包括宏伟壮丽的吴哥窟。位于柬埔寨西北部，这座城市完美融合了法式殖民建筑、热闹繁华的市场、丰富多元的美食文化，以及历史悠久、底蕴深厚的高棉文化遗产', 'Siem Reap is one of the most important provinces in Cambodia, best known as the gateway to the Angkor Archaeological Park, including the famous Angkor Wat temple. The name "Siem Reap" means "Defeat of Siam," referring to historic conflicts between the Khmer Empire and Siam (modern-day Thailand).

The region became prominent during the Angkor period (9th–15th century), when it was the center of the Khmer Empire. After the decline of Angkor, the area was gradually abandoned and covered by forest.

In the 19th century, French explorers rediscovered the ancient temples, bringing international attention to Siem Reap. Today, it is Cambodia’s top tourist destination and a UNESCO World Heritage Site due to its cultural and historical significance.', 'ខេត្តសៀមរាប គឺជាខេត្តមួយសំខាន់បំផុតនៅកម្ពុជា ហើយមានភាពល្បីល្បាញជាច្រកចូលទៅកាន់តំបន់អង្គរ ដែលរួមមានប្រាសាទអង្គរវត្តដ៏ល្បីល្បាញ។

ឈ្មោះ “សៀមរាប” មានន័យថា “សៀមចាញ់” ដែលទាក់ទងនឹងប្រវត្តិសាស្ត្រការប្រយុទ្ធរវាងអាណាចក្រខ្មែរ និងសៀម (ថៃបច្ចុប្បន្ន)។

តំបន់នេះមានសារៈសំខាន់ខ្លាំងក្នុងសម័យអង្គរ (សតវត្សទី ៩–១៥) ពេលដែលអាណាចក្រខ្មែររីកចម្រើនខ្លាំង។ បន្ទាប់ពីអង្គរធ្លាក់ចុះ តំបន់នេះត្រូវបានទុកចោល និងគ្របដណ្តប់ដោយព្រៃ។

នៅសតវត្សទី ១៩ អ្នកស្រាវជ្រាវបារាំងបានរកឃើញប្រាសាទអង្គរឡើងវិញ និងធ្វើឲ្យសៀមរាបក្លាយជាកន្លែងល្បីល្បាញលើពិភពលោក។ សព្វថ្ងៃ វាជាគោលដៅទេសចរណ៍សំខាន់បំផុតរបស់កម្ពុជា។', '暹粒是柬埔寨最重要的省份之一，以吴哥考古公园的入口而闻名，其中包括著名的吴哥窟。

“暹粒”意为“击败暹罗”，源于历史上高棉帝国与暹罗（今泰国）之间的战争。

在吴哥时期（9世纪至15世纪），该地区是高棉帝国的中心，非常繁荣。吴哥衰落后，该地区逐渐被遗弃并被森林覆盖。

19世纪，法国探险家重新发现了吴哥古迹，使暹粒再次受到世界关注。如今，它是柬埔寨最重要的旅游城市，也是联合国教科文组织世界遗产地。', 21, 'Siem Reap is home to some of Cambodia''s most iconic attractions, including Angkor Wat, Bayon Temple, Ta Prohm, Banteay Srei, Phnom Kulen National Park, Tonlé Sap Lake, Pub Street, Angkor National Museum, Cambodian Cultural Village, and the Angkor Night Market. These destinations showcase the province''s rich history, natural beauty, and vibrant local culture.', 'សៀមរាបមានតំបន់ទេសចរណ៍ល្បីល្បាញជាច្រើន រួមមាន ប្រាសាទអង្គរវត្ត ប្រាសាទបាយ័ន ប្រាសាទតាព្រហ្ម ប្រាសាទបន្ទាយស្រី ឧទ្យានជាតិភ្នំគូលែន បឹងទន្លេសាប ផាប់ស្ទ្រីត សារមន្ទីរជាតិអង្គរ ភូមិវប្បធម៌កម្ពុជា និងផ្សាររាត្រីអង្គរ។ ទីកន្លែងទាំងនេះបង្ហាញពីប្រវត្តិសាស្ត្រ វប្បធម៌ និងសម្រស់ធម្មជាតិដ៏អស្ចារ្យរបស់ខេត្តសៀមរាប។', '暹粒拥有柬埔寨最著名的旅游景点，包括吴哥窟、巴戎寺、塔布隆寺、女王宫、库伦山国家公园、洞里萨湖、酒吧街、吴哥国家博物馆、柬埔寨文化村以及吴哥夜市。这些景点充分展现了暹粒悠久的历史、壮丽的自然风光和丰富的高棉文化。', 'Siem Reap offers a wide variety of traditional Khmer dishes such as Fish Amok, Num Banh Chok (Khmer noodles), Beef Lok Lak, Khmer Red Curry, Grilled River Fish, Palm Cake, Sticky Rice with Mango, and many delicious street foods available throughout the city.', 'សៀមរាបមានម្ហូបប្រពៃណីខ្មែរជាច្រើន ដូចជា អាម៉ុកត្រី នំបញ្ចុក សាច់គោឡុកឡាក់ ការីខ្មែរ ត្រីដុត នំត្នោត បាយដំណើបស្វាយទុំ និងអាហារតាមដងផ្លូវជាច្រើនដែលមានរសជាតិឆ្ងាញ់។', '暹粒拥有丰富的高棉传统美食，包括阿莫克鱼、柬埔寨米线（Num Banh Chok）、柬式黑椒牛肉（Lok Lak）、高棉红咖喱、烤河鱼、棕榈蛋糕、芒果糯米饭以及各种美味的街头小吃。', 'Siem Reap celebrates many important festivals throughout the year, including Khmer New Year (Angkor Sankranta), the Water Festival, Pchum Ben, Visak Bochea Day, and various cultural performances held at Angkor Archaeological Park.', 'សៀមរាបប្រារព្ធពិធីបុណ្យសំខាន់ៗជាច្រើន រួមមាន បុណ្យចូលឆ្នាំខ្មែរ (អង្គរសង្ក្រាន្ត) បុណ្យអុំទូក បុណ្យភ្ជុំបិណ្ឌ បុណ្យវិសាខបូជា និងការសម្តែងសិល្បៈវប្បធម៌ជាច្រើននៅតំបន់អង្គរ។', '暹粒全年举办许多重要节日，包括高棉新年（吴哥宋干节）、送水节、亡人节、卫塞节，以及吴哥古迹公园内举办的各种传统文化表演和庆典活动。', 'The best time to visit Siem Reap is from November to February, when the weather is cool and dry. This period is ideal for exploring Angkor Wat, cycling through the temples, enjoying outdoor activities, and experiencing local festivals.', 'ពេលវេលាល្អបំផុតសម្រាប់ទស្សនាខេត្តសៀមរាប គឺចាប់ពីខែវិច្ឆិកា ដល់ខែកុម្ភៈ ព្រោះអាកាសធាតុត្រជាក់ និងស្ងួត សមស្របសម្រាប់ទស្សនាប្រាសាទអង្គរ ជិះកង់ កម្សាន្តក្រៅផ្ទះ និងចូលរួមពិធីបុណ្យនានា។', '游览暹粒的最佳时间是每年11月至次年2月，此时天气凉爽干燥，非常适合参观吴哥窟、骑行探索古迹、参加户外活动以及体验当地传统节日。```

These texts are suitable for populating the `attractions_*`, `food_*`, `festival_*`, and `best_time_*` fields in your `province_details` table.', '2026-06-26 02:35:11.748479', '2026-06-26 02:35:11.748479');
COMMIT;

