BEGIN;
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (12, 'Kratie', 'ក្រចេះ', '桔井', 'Kratie province is famous for having many dolphins in the Mekong River.', 'ខេត្តក្រចេះល្បីដោយសារមានសត្វផ្សោតជាច្រើននៅទន្លេមេគង្គ។', '桔井省因湄公河中有许多河豚而闻名。', 'https://www.khmertimeskh.com/wp-content/uploads/2026/04/MM-7.jpg', '2026-06-25 08:39:04.113177', '2026-07-01 10:19:38.346366');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (4, 'Battambang', 'បាត់ដំបង', '马德望', 'Battambang is famous for its rice production and colonial buildings.', 'បាត់ដំបងល្បីដោយសារផលិតស្រូវ និងអាគារបុរាណសម័យអាណានិគម។', '马德望以水稻生产和殖民建筑闻名。', 'data:image/jpeg;base64,', '2026-06-25 08:39:04.113177', '2026-07-01 07:36:00.999301');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (6, 'Kampong Chhnang', 'កំពង់ឆ្នាំង', '磅清扬', 'Kampong Chhnang is known for pottery and floating villages.', 'កំពង់ឆ្នាំងល្បីដោយសារគ្រឿងដីនិងភូមិទឹក។', '磅清扬以陶器和水上村庄闻名。', 'https://i0.wp.com/www.cambodialifestyle.com/wp-content/uploads/2024/04/Kampong-Chhnang-1.jpg?fit=1024%2C576&ssl=1', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (7, 'Kampong Speu', 'កំពង់ស្ពឺ', '磅士卑', 'Kampong Speu is known for palm sugar production.', 'កំពង់ស្ពឺល្បីដោយសារផលិតស្ករត្នោត។', '磅士卑以棕糖生产闻名。', 'https://www.asiakingtravel.com/cuploads/files/Kampong-Speu-1(2).jpg', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (8, 'Kampong Thom', 'កំពង់ធំ', '磅通', 'Kampong Thom is home to ancient temples like Sambor Prei Kuk.', 'កំពង់ធំជាទីតាំងប្រាសាទបុរាណសំបូរព្រៃគុក។', '磅通拥有三波雷古寺等古迹。', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRZGmtZHda9w0MfbY8_HWEnDdckn9RqjmwloV5H_stepw&s=10', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (9, 'Kampot', 'កំពត', '贡布', 'Kampot is famous for pepper and seaside scenery.', 'កំពតល្បីដោយម្រេច និងទេសភាពសមុទ្រ។', '贡布以胡椒和海景闻名。', 'https://www.neverendingvoyage.com/wp-content/uploads/2014/03/durian-statue-kampot-cambodia.jpg', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (10, 'Kandal', 'កណ្ដាល', '干丹', 'Kandal surrounds Phnom Penh and is highly developed.', 'កណ្ដាលព័ទ្ធជុំវិញភ្នំពេញ និងមានការអភិវឌ្ឍខ្ពស់។', '干丹环绕金边，发展迅速。', 'https://i0.wp.com/www.cambodialifestyle.com/wp-content/uploads/2024/04/Kandal7.jpg?fit=990%2C660&ssl=1', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (11, 'Koh Kong', 'កោះកុង', '戈公', 'Koh Kong is known for its coastline and rainforest.', 'កោះកុងល្បីដោយឆ្នេរ និងព្រៃភ្នំ។', '戈公以海岸和雨林闻名。', 'https://i0.wp.com/www.cambodialifestyle.com/wp-content/uploads/2024/04/Koh-Kong3.jpg?fit=1024%2C722&ssl=1', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (14, 'Oddar Meanchey', 'ឧត្ដរមានជ័យ', '奥多棉吉', 'Oddar Meanchey is located near the Thai border.', 'ឧត្ដរមានជ័យស្ថិតជិតព្រំដែនថៃ។', '奥多棉吉靠近泰国边境。', 'https://i0.wp.com/www.cambodialifestyle.com/wp-content/uploads/2024/03/ministry-of-tourism-cambodia-2019-02-18-07-39-42am-Oddar-Meanchey-01.jpg', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (15, 'Pailin', 'ប៉ៃលិន', '拜林', 'Pailin is known for gemstones and mountains.', 'ប៉ៃលិនល្បីដោយត្បូង និងភ្នំ។', '拜林以宝石和山区闻名。', 'https://cambodia.thajsko.com/wp-content/uploads/Pailin-02.jpg', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (16, 'Phnom Penh', 'ភ្នំពេញ', '金边', 'Phnom Penh is the capital city of Cambodia.', 'ភ្នំពេញជារដ្ឋធានីនៃប្រទេសកម្ពុជា។', '金边是柬埔寨首都。', 'https://media02.stockfood.com/largepreviews/MjIwMjkzMzAwNQ==/71062355-Camdodia-Phnom-Penh-Province-Phnom-Penh-town-the-Phnom-Penh-Independent-monument-built-in-1958-looks-like.jpg', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (17, 'Preah Sihanouk', 'ព្រះសីហនុ', '西哈努克', 'Preah Sihanouk is famous for beaches and islands.', 'ព្រះសីហនុល្បីដោយឆ្នេរ និងកោះ។', '西哈努克以海滩和岛屿闻名。', 'https://i0.wp.com/www.cambodialifestyle.com/wp-content/uploads/2024/04/Preah-Sihanouk1.jpg?fit=1920%2C1200&amp;ssl=1', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (18, 'Preah Vihear', 'ព្រះវិហារ', '柏威夏', 'Preah Vihear is known for its ancient temple on a mountain.', 'ព្រះវិហារល្បីដោយប្រាសាទលើភ្នំ។', '柏威夏以山顶寺庙闻名。', 'https://i0.wp.com/www.cambodialifestyle.com/wp-content/uploads/2024/04/Preah-Vihear-1.jpg', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (19, 'Pursat', 'ពោធិ៍សាត់', '菩萨省', 'Pursat is known for marble carving and forests.', 'ពោធិ៍សាត់ល្បីដោយចម្លាក់ថ្មម៉ាប និងព្រៃ។', '菩萨省以大理石雕刻和森林闻名。', 'https://i0.wp.com/www.cambodialifestyle.com/wp-content/uploads/2024/04/Pursat1.jpg?fit=1024%2C576&ssl=1', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (20, 'Ratanakiri', 'រតនគិរី', '腊塔纳基里', 'Ratanakiri is known for volcanic lakes and ethnic minorities.', 'រតនគិរីល្បីដោយបឹងភ្នំភ្លើង និងជនជាតិភាគតិច។', '腊塔纳基里以火山湖和少数民族闻名。', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTj1OlYTQRqPv2zCiMxYB_1Ku64-hzVd60yZsqwfe0Slg&s=10', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (23, 'Svay Rieng', 'ស្វាយរៀង', '柴桢', 'Svay Rieng is a border province with Vietnam.', 'ស្វាយរៀងជាខេត្តព្រំដែនជាមួយវៀតណាម។', '柴桢是与越南接壤的边境省份。', 'https://upload.wikimedia.org/wikipedia/commons/e/ec/Sangkat_Svay_Rieng%2C_Krong_Svay_Rieng%2C_Cambodia_-_panoramio.jpg', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (24, 'Takeo', 'តាកែវ', '茶胶', 'Takeo is considered the cradle of Khmer civilization.', 'តាកែវត្រូវបានចាត់ទុកជាអាណាចក្រខ្មែរ​ដំបូង។', '茶胶被认为是高棉文明的发源地。', 'https://www.ppmlgroup.com/wp-content/uploads/2022/02/takeo-icon_orig.jpg', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (21, 'Siem Reap', 'សៀមរាប', '暹粒', 'Siem Reap is famous for Angkor Wat temple.', 'សៀមរាបល្បីល្បាញដោយសារប្រាសាទអង្គរវត្ត។', '暹粒因吴哥窟寺庙而闻名。', 'https://cdn.adventure-life.com/81/11/8/5qg25p24/1300x820.webp', '2026-06-25 08:39:04.113177', '2026-06-26 08:31:46.594398');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (22, 'Stung Treng', 'ស្ទឹងត្រែង', '上丁', 'Stung Treng is located along the Mekong River in northern Cambodia.', 'ស្ទឹងត្រែងស្ថិតនៅភាគខាងជើងតាមដងទន្លេមេគង្គ។', '上丁位于柬埔寨北部湄公河沿岸。', 'https://d122axpxm39woi.cloudfront.net/images/destinations/origin/5da598ba67f32.png', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (13, 'Mondulkiri', 'មណ្ឌលគិរី', '蒙多基里', 'Mondulkiri is known for hills, forests, and waterfalls.', 'មណ្ឌលគិរីល្បីដោយភ្នំ ព្រៃ និងទឹកធ្លាក់។', '蒙多基里以山林和瀑布闻名。', 'https://i0.wp.com/www.cambodialifestyle.com/wp-content/uploads/2024/04/Mondulkiri3.jpg?fit=1024%2C751&ssl=1', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (25, 'Tbong Khmum', 'ត្បូងឃ្មុំ', '特本克蒙', 'Tbong Khmum is known for agriculture and rubber plantations.', 'ត្បូងឃ្មុំល្បីដោយកសិកម្ម និងចម្ការកៅស៊ូ។', '特本克蒙以农业和橡胶种植园闻名。', 'https://i0.wp.com/www.cambodialifestyle.com/wp-content/uploads/2024/04/Tbong-Khmum-3.jpg?fit=600%2C428&ssl=1', '2026-06-25 08:39:04.113177', '2026-06-25 08:39:04.113177');
INSERT INTO "public"."provinces" ("id", "name_en", "name_kh", "name_zh", "des_en", "des_kh", "des_zh", "image", "createdAt", "updatedAt") VALUES (3, 'Banteay meanchey', 'បន្ទាយមានជ័យ', '班迭棉吉', 'Banteay Meanchey is known for border trade with Thailand.', 'បន្ទាយមានជ័យល្បីដោយសារពាណិជ្ជកម្មព្រំដែនជាមួយថៃ។', '班迭棉吉以与泰国的边境贸易而闻名。', 'https://www.asiakingtravel.com/cuploads/files/Banteay%20Meanchey%20-%202.jpg', '2026-06-25 08:39:04.113177', '2026-07-01 07:33:29.104672');
COMMIT;

